def prime_num(n):
    # 0 and 1 are not prime numbers
    if n <= 1:
        return False

    # Check for factors from 2 to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Test the function with the provided example
print(prime_num(13)) # Expected output: True
